        n %= use[d];
        if (n == 0) return sum;
        int option1 = computeMin(use[d] - n, d - 1) + d;
        int option2 = computeMin(n, d - 1);
        return sum + Math.min(option1, option2);
    }

    public static void main(String[] args) {
